"""kb_where.py —— 「某份文件/某段文字到底在不在库里」的**全目录**检索。

用法：
    python tools/kb_where.py "Shiryaev"
    python tools/kb_where.py "d6dd00132g" --files      # 只列文件
    python tools/kb_where.py "practical shortcuts" --dirs raw,references
    python tools/kb_where.py --dirs               # 列出受检索的目录及其现有文件数
    python tools/kb_where.py --selftest

为什么要有这个工具
------------------
2026-09-26 实测事故：`evidence/rows-ch2.md`、`rows-ch4.md`、`prior-art-verification.md`
**三处独立检索**都断言「Shiryaev et al. 2026 全文不在库内」，并**都正确写明了
"在哪份文件上检索"**——这正是本库纪律第 1 条的要求。但三次枚举的范围是
`raw/` + `wiki/`，而该文全文一直在
`projects/references/` 内。

⇒ 教训：**「写明检索范围」只在范围本身完备时才有意义。**
   范围不完备时，写明了反而让错误的「0 命中」显得可信。

本库的资料实际分布在**四个**目录；任一遗漏都会把"存在"报成"不存在"：

    raw/                              # 一手资料（clippings/ literatures-md/ _pdf/ …）
    wiki/                             # 知识页（sources/ concepts/ entities/ …）
    projects/references/   # 参考文献全文抓取件
    projects/               # 综述工程自身（evidence/ draft/ …）

另有 `wiki/.claude-rename/`（历史重命名备份，312 文件）与 `wiki/.index/`（派生数据），
二者**已被本库检索层排除**，本工具同样默认排除。

本库纪律映射
------------
* 「凡断言『原文缺失』，必须写明是在哪个文件上检索的」
  ⇒ 本工具输出**逐目录的命中数**，可直接粘贴进取证文件，代替手写 grep 命令。
* 「宽松的校验器等于没有校验器」
  ⇒ 本工具**不做模糊匹配**：默认按归一化后的**子串**精确命中，
     归一化仅含换行/连字/弯引号（与 `check_draft.norm_variants` 同口径），
     并**同时给出两个断字变体的命中数**，避免"删连字符/保留连字符"两可造成的假阴性。
"""
import io
import os
import re
import sys

# 🔴 **必须在任何 print 之前**把 stdout 切到 UTF-8。
#    本工具的输出里含 `⇒`（U+21D2）与 `⚠️`，**都不在 cp936 里** ⇒ 在 Windows 默认
#    代码页下，本工具会 `UnicodeEncodeError` 直接崩掉——而且崩在"⇒ 零命中"那一行，
#    也就是**它最该给出答案的那一刻**（实测：`--help` 与普通调用都崩，rc=1）。
#    本工具是 CLAUDE.md 明令「断言『库内无 X』之前必跑」的那一个，
#    崩在默认控制台等于该纪律无法执行。
try:                                                           # noqa: SIM105
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")
except Exception:                                              # noqa: BLE001
    pass

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)

# (显示名, 相对路径, 是否默认启用)
SEARCH_DIRS = [
    ("raw", "raw", True),
    ("wiki", "wiki", True),
    # ⚠️ Phase 3 已把综述工程归档到 `projects/`
    #    迁到 `projects/`。**这个工具的路径错一处，
    #    整套「四目录完备检索」纪律就静默失效**——而它正是为那次「三处独立检索
    #    都断言 Shiryaev 不在库内，其实在 references/」的事故而写的。
    ("review-references", "projects/references", True),
    ("review-project", "projects", True),
    ("archive", "projects/_superseded", False),
]

EXCLUDE_SEGMENTS = {".index", ".claude-rename", "__pycache__", ".git",
                    "tmp_img"}          # 临时脚本/图片目录，会污染「库内命中」计数
# 🔴 **cycle-8 审稿 Minor 2**：项目根下有 60+ 个 `tmp_*.py`（调试/一次性脚本），
#    它们落在 `review-project` 目录内 ⇒ **污染「库内检索」的命中计数**
#    （审稿人实测：多行命中计数包含了它们）。临时件**不携带库内知识**，一律排除。
#    ⚠️ 只按**文件名前缀**排除，不排除正式文件（如 `tmp` 不在正式文件名中）。
EXCLUDE_PREFIXES = ("tmp_", "tmp-")
EXCLUDE_BASENAMES = {"log.md"}          # 历史存档，不参与检索（与 check_draft 同口径）

LIGATURES = {"ﬁ": "fi", "ﬂ": "fl", "ﬀ": "ff", "ﬃ": "ffi", "ﬄ": "ffl"}
SMARTQUOTE = {"’": "'", "‘": "'", "“": '"', "”": '"'}


def variants(text):
    """归一化出两个断字变体（与 check_draft.norm_variants 同口径）。

    为什么要两个：`engi-\\nneering`（应删连字符）与 `self-\\nvalidation`
    （应保留连字符）**先验不可区分**，只取一种会漏掉另一种。
    """
    s = text.replace("\r\n", "\n").replace("\r", "\n")
    for k, v in LIGATURES.items():
        s = s.replace(k, v)
    for k, v in SMARTQUOTE.items():
        s = s.replace(k, v)
    out = []
    for hyphen in ("", "-"):
        out.append(re.sub(r"\s+", " ", re.sub(r"-\n", hyphen, s)))
    return out


def iter_files(dirs):
    for name, rel, _default in dirs:
        base = os.path.join(ROOT, rel.replace("/", os.sep))
        if not os.path.isdir(base):
            continue
        for dp, dns, fns in os.walk(base):
            dns[:] = [d for d in dns if d not in EXCLUDE_SEGMENTS]
            for fn in fns:
                if not fn.lower().endswith(".md"):
                    continue
                if fn in EXCLUDE_BASENAMES:
                    continue
                if fn.startswith(EXCLUDE_PREFIXES):
                    continue
                yield name, os.path.join(dp, fn)


def search(needle, dirs, files_only=False):
    """-> {dir_name: [(relpath, lineno, snippet), ...]}, {dir_name: n_files_scanned}

    ⚠️ 语料过 `variants()`（连字/弯引号/断字归一），**检索词也必须过**
    ——否则从稿子里复制的 `ﬁ`、智能引号、跨行断字会**假阴性**。
    本工具的立身之本就是"否定性结论"，假阴性正是它最不能出的错。
    """
    hits, scanned = {}, {}
    for name, _, _ in dirs:
        hits[name] = []
        scanned[name] = 0
    needles = [v.lower() for v in variants(needle)] or [needle.lower()]
    for dname, path in iter_files(dirs):
        scanned[dname] = scanned.get(dname, 0) + 1
        try:
            txt = io.open(path, encoding="utf-8", errors="replace").read()
        except Exception:
            continue
        vs = variants(txt)
        if not any(n in v.lower() for v in vs for n in needles):
            continue
        rel = os.path.relpath(path, ROOT).replace(os.sep, "/")
        # 定位行号（用原文本，不用归一化文本，才能给出可点击的行号）
        ln = None
        for i, line in enumerate(txt.replace("\r\n", "\n").split("\n"), 1):
            if any(n in re.sub(r"\s+", " ", line).lower() for n in needles):
                ln = i
                break
        hits[dname].append((rel, ln))
    return hits, scanned


def report(needle, dirs, scanned, hits, files_only=False):
    total = sum(len(v) for v in hits.values())
    if files_only:
        # `--files` 此前**只写在 docstring 里**、既没解析也没实现（`files_only`
        # 参数从头到尾没被读过）⇒ 用户照文档敲会被静默忽略、拿到完整报告。
        for name, _, _ in dirs:
            for rel, ln in hits.get(name, []):
                print("%s%s" % (rel, "" if ln is None else ":%d" % ln))
        return 0
    print("=== kb_where: %r ===" % needle)
    print("检索根: %s" % ROOT)
    print("排除: %s ｜ 文件名排除: %s"
          % (", ".join(sorted(EXCLUDE_SEGMENTS)), ", ".join(sorted(EXCLUDE_BASENAMES))))
    print()
    print("%-20s %8s %8s" % ("目录", "扫描文件", "命中文件"))
    print("-" * 40)
    for name, _, default in dirs:
        mark = "" if default else "  (默认关闭)"
        print("%-20s %8d %8d%s" % (name, scanned.get(name, 0), len(hits.get(name, [])), mark))
    print("-" * 40)
    print("%-20s %8s %8d" % ("合计", "", total))
    print()
    if total == 0:
        print("⇒ 零命中。**写进取证文件时必须照抄上面的目录清单**，")
        print("  否则读者无从判断你检索的范围是否完备。")
        # 🔴 零命中是**有效答案**，不是工具失败。旧版返回 1 —— 调用脚本/Agent
        #    若按"非零=工具坏了"处理，就会把"确实不在库里"误读成"检索没跑成"。
        #    非零退出码现在只保留给真正的错误（目录不可用等）。
        return 0
    for name, _, _ in dirs:
        if not hits.get(name):
            continue
        print("[%s]" % name)
        for rel, ln in hits[name]:
            print("   %s%s" % (rel, "" if ln is None else ":%d" % ln))
        print()
    return 0


def _anchor_present(dir_rel, term):
    """该目录里是否**物理存在**含 term 的文件（用于判断源库专属锚点是否适用）。

    正例 1–3 是**源库的事故回归夹具**（Shiryaev / A-Lab 等具体语料），不是通用不变量：
    全新空库没有这些内容，若强行断言就会**假 FAIL**（把「本库没有这段语料」错报成
    「检索坏了」）。故仅在锚点确实存在时才断言；不存在则跳过（信息性）。
    """
    d = os.path.join(ROOT, dir_rel)
    if not os.path.isdir(d):
        return False
    t = term.lower()
    for dp, _, fs in os.walk(d):
        for f in fs:
            try:
                if t in io.open(os.path.join(dp, f), encoding="utf-8",
                                errors="replace").read().lower():
                    return True
            except Exception:                              # noqa: BLE001
                pass
    return False


def selftest():
    """正例反例夹逼 —— 只测「该找到的找到了」会漏掉「该漏的漏了没有」。"""
    fails = []

    _rr = next((d[1] for d in SEARCH_DIRS if d[0] == "review-references"), None)

    # 正例 1：Shiryaev 全文须在 review-references 里找到（源库事故回归；无该语料则跳过）
    if _rr and _anchor_present(_rr, "Shiryaev"):
        hits, scanned = search("Shiryaev", [d for d in SEARCH_DIRS if d[2]])
        if not hits.get("review-references"):
            fails.append("正例1：`Shiryaev` 未在 review-references 命中（事故回归夹具）")
        hits2, _ = search("d6dd00132g", [d for d in SEARCH_DIRS if d[2]])
        if not hits2.get("review-references"):
            fails.append("正例2：`d6dd00132g` 未在 review-references 命中")
    else:
        print("  [skip] 正例1/2：本库不含 Shiryaev 事故语料（源库专属锚点，跳过）")

    # 正例 3：raw 里的既有内容仍须命中（同样仅在锚点存在时断言）
    if _anchor_present("raw", "A-Lab"):
        hits3, _ = search("A-Lab", [d for d in SEARCH_DIRS if d[2]])
        if not hits3.get("raw"):
            fails.append("正例3：`A-Lab` 未在 raw 命中")
    else:
        print("  [skip] 正例3：本库 raw 不含 `A-Lab`（源库专属锚点，跳过）")

    # 反例 1：绝不存在的串必须零命中（否则是宽度过松）
    hits4, _ = search("zzz-绝不存在-qqq-20260926", [d for d in SEARCH_DIRS if d[2]])
    if sum(len(v) for v in hits4.values()) != 0:
        fails.append("反例1：不存在的串被命中（匹配过松）")

    # 反例 2：`.index` 与 `log.md` 必须被排除
    hits5, _ = search("concept linked by", [d for d in SEARCH_DIRS if d[2]])
    for name, lst in hits5.items():
        for rel, _ln in lst:
            if ".index" in rel or rel.endswith("/log.md") or rel == "wiki/log.md":
                fails.append("反例2：派生/存档文件未被排除: %s" % rel)

    # 正例 4：断字两变体 —— 归一化必须能同时吃下"删连字符"与"保留连字符"两种写法
    vs = variants("engi-\nneering and self-\nvalidation")
    if not any("engineering" in v for v in vs):
        fails.append("正例4：`engi-\\nneering` 未被归一为 engineering")
    if not any("self-validation" in v for v in vs):
        fails.append("正例4：`self-\\nvalidation` 未保留连字符形式")

    # 正例 5：**检索词也必须过 variants()**（2026-10-10 修）
    #   语料过了归一化而检索词没过的后果是**假阴性**：从稿子里复制的 `ﬁ`、智能引号、
    #   跨行断字都会"明明在库里却零命中"——而本工具的价值全在否定性结论上。
    hits5, _ = search("engineering", [("t", "tools", True)])
    if not any("engi-\nneering" in (io.open(os.path.join(ROOT, r), encoding="utf-8",
                                             errors="replace").read())
               for r, _ in hits5.get("t", [])) and not hits5.get("t"):
        # tools/ 里没有该串也无妨；真正的断言在下面的夹具文件上
        pass
    _probe_dir = os.path.join(HERE, "_kb_where_probe")
    _probe_rel = "tools/_kb_where_probe"      # 相对 ROOT（iter_files 以 ROOT 为基准）
    try:
        os.makedirs(_probe_dir, exist_ok=True)
        with io.open(os.path.join(_probe_dir, "pr.md"), "w", encoding="utf-8") as f:
            f.write("The ﬁnal engi-\nneering result and a “smart” quote.\n")
        h_probe, _s = search("final engineering", [("probe", _probe_rel, True)],
                             files_only=True)
        if not h_probe.get("probe"):
            fails.append("正例5：检索词未过 variants() ⇒ 连字/断字篇假阴性")
        h_probe2, _s2 = search("smart", [("probe", _probe_rel, True)])
        if not h_probe2.get("probe"):
            fails.append("正例5b：智能引号篇假阴性")
        # 反例 4：确不存在的串必须零命中（否则夹具本身没意义）
        h_probe3, _s3 = search("绝不存在的串-xyz-qqq", [("probe", _probe_rel, True)])
        if h_probe3.get("probe"):
            fails.append("反例4：不存在的串竟有命中")
        # 反例 5：--files 模式必须只输出路径（不得混入表头）
        import contextlib as _cl
        _buf = io.StringIO()
        with _cl.redirect_stdout(_buf):
            report("smart", [("probe", _probe_rel, True)],
                   {"probe": 1}, {"probe": [("tools/_kb_where_probe/pr.md", 2)]},
                   files_only=True)
        if "目录" in _buf.getvalue() or "tools/_kb_where_probe/pr.md:2" not in _buf.getvalue():
            fails.append("反例5：--files 输出混入表头或丢了路径")
        # 反例 6：零命中必须是**成功**（退出码 0），否则脚本会把"确实不在库里"误读成工具失败
        _buf2 = io.StringIO()
        with _cl.redirect_stdout(_buf2):
            rc0 = report("绝不存在的串-xyz-qqq", [("probe", _probe_rel, True)],
                         {"probe": 1}, {"probe": []})
        if rc0 != 0:
            fails.append("反例6：零命中返回了非零退出码")
    finally:
        import shutil as _sh
        _sh.rmtree(_probe_dir, ignore_errors=True)

    if fails:
        # ⚠️ 旧版把失败详情**写成文件**（tools/_kb_where_selftest.txt）——
        #    一个"只读自检"带写盘副作用，还会被 kb_toolcheck 的写盘防呆判成意外改动。
        #    现在直接打 stderr。
        print("[SELFTEST FAIL] %d 项：" % len(fails), file=sys.stderr)
        for f in fails:
            print("  - " + f, file=sys.stderr)
        return 1
    print("[SELFTEST PASS] 5 正例 + 5 反例全部通过"
          "（含 `Shiryaev` 必须命中 references/ 的事故回归夹具）")
    return 0


def main():
    args = [a for a in sys.argv[1:]]
    if "--selftest" in args:
        return selftest()

    # --dirs：列出受检索目录及其现状
    if "--dirs" in args:
        print("受检索目录（ROOT=%s）：" % ROOT)
        for name, rel, default in SEARCH_DIRS:
            base = os.path.join(ROOT, rel.replace("/", os.sep))
            n = sum(1 for _ in iter_files([(name, rel, default)]))
            print("  %-18s %-52s 现有 %4d 个 .md%s"
                  % (name, rel + "/", n, "" if default else "   [非默认]"))
        print("\n⚠️ 断言「库内无某文件」前，必须在本清单**全部默认目录**上检索过。")
        return 0

    dirs = [d for d in SEARCH_DIRS if d[2]]
    for a in args:
        if a.startswith("--dirs="):
            want = set(a.split("=", 1)[1].split(","))
            dirs = [d for d in SEARCH_DIRS if d[0] in want or d[1] in want]
    files_only = "--files" in args          # 旧版 docstring 有此开关、代码里没有
    needles = [a for a in args if not a.startswith("--")]
    if not needles:
        print(__doc__)
        return 2

    rc = 0
    for needle in needles:
        hits, scanned = search(needle, dirs)
        rc |= report(needle, dirs, scanned, hits, files_only=files_only)
    return rc


if __name__ == "__main__":
    sys.exit(main())
